class Solution {
    public int minNumberOfSemesters(int n,int[][] relations,int k){
        int[] prerequisite=new int[n];
        for(int[] relation:relations)prerequisite[relation[1]-1]|=1<<(relation[0]-1);
        int total=1<<n,inf=100;
        int[] dp=new int[total];
        Arrays.fill(dp,inf);
        dp[0]=0;
        for(int mask=0;mask<total;mask++){
            if(dp[mask]==inf)continue;
            int available=0;
            for(int course=0;course<n;course++)if((mask&(1<<course))==0&&(prerequisite[course]&mask)==prerequisite[course])available|=1<<course;
            if(Integer.bitCount(available)<=k)dp[mask|available]=Math.min(dp[mask|available],dp[mask]+1);
            else for(int subset=available;subset>0;subset=(subset-1)&available)if(Integer.bitCount(subset)==k)dp[mask|subset]=Math.min(dp[mask|subset],dp[mask]+1);
        }
        return dp[total-1];
    }
}

code.kotlin:
class Solution {
    fun minNumberOfSemesters(n:Int,relations:Array<IntArray>,k:Int):Int{
        val prerequisite=IntArray(n);
        for(relation in relations)prerequisite[relation[1]-1]=prerequisite[relation[1]-1]or(1 shl (relation[0]-1));
        val total=1 shl n;
        val dp=IntArray(total){
            100
        };
        dp[0]=0;
        for(mask in 0 until total){
            if(dp[mask]==100)continue;
            var available=0;
            for(course in 0 until n)if(mask and (1 shl course)==0&&prerequisite[course] and mask==prerequisite[course])available=available or(1 shl course);
            if(Integer.bitCount(available)<=k)dp[mask or available]=minOf(dp[mask or available],dp[mask]+1)else{
                var subset=available;
                while(subset>0){
                    if(Integer.bitCount(subset)==k)dp[mask or subset]=minOf(dp[mask or subset],dp[mask]+1);
                    subset=(subset-1)and available
                }
            }
        };
        return dp.last()
    }
}

